<div class="media-picker"><select x-model="values.{{ $mediaKey }}" :disabled="uploads>0" aria-label="انتخاب رسانه" @change="selectedMedia['{{ $mediaKey }}']=(references.media||[]).find(m=>String(m.id)===String(values.{{ $mediaKey }}))||null" @if($mediaRequired??false) required @endif><option value="">انتخاب از کتابخانه</option><template x-for="entry in (references.media||[]).filter(m=>{{ ($mediaAccept??'image/*')==='image/*'?'String(m.mime_type).startsWith(\'image/\')':'true' }})" :key="entry.id"><option :value="String(entry.id)" x-text="entry.alt||entry.original_name||('رسانه '+entry.id)"></option></template></select><label class="upload-button"><x-icon name="upload" size="17" /><span x-text="uploads?'در حال بارگذاری…':'بارگذاری فایل'"></span><input type="file" accept="{{ $mediaAccept??'image/jpeg,image/png,image/webp' }}" :disabled="uploads>0" @change="uploadField($event,'{{ $mediaKey }}')"></label><div class="selected-media" x-cloak x-show="values.{{ $mediaKey }}"><template x-if="selectedMedia['{{ $mediaKey }}']?.mime_type?.startsWith('image/')"><img :src="mediaUrl({id:values.{{ $mediaKey }}})" :alt="selectedMedia['{{ $mediaKey }}']?.alt||''"></template><span x-text="selectedMedia['{{ $mediaKey }}']?.alt||selectedMedia['{{ $mediaKey }}']?.original_name||''"></span><button type="button" :disabled="uploads>0" aria-label="حذف انتخاب" @click="values.{{ $mediaKey }}=null;selectedMedia['{{ $mediaKey }}']=null"><x-icon name="x" size="16" /></button></div></div>
